.tl em.bd{position:absolute;top:4px;right:4px;left:auto;bottom:auto;z-index:2}

/* ===== theme variables + panels ===== */
:root{--bgc:#0d1220}
.sc{background:radial-gradient(circle at 90% 0%,color-mix(in srgb,var(--ac) 16%,transparent),transparent 45%),radial-gradient(circle at 0% 100%,color-mix(in srgb,var(--gd) 10%,transparent),transparent 40%),var(--bgc)}
