.hav{padding:0;border-radius:50%;cursor:pointer;line-height:0}
.pn{position:absolute;left:12px;right:12px;bottom:36px;z-index:30;padding:14px;border-radius:18px;background:color-mix(in srgb,var(--bgc) 86%,#fff 14%);border:1px solid rgba(255,255,255,.16);box-shadow:0 14px 34px rgba(0,0,0,.55);color:#eaf0ff}
.ph2{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px}
