      <span>HSR / FIELD RECORD</span>
    </div>
  </div>

  <script>
    (() => {
      const own = document.currentScript && document.currentScript.closest ? document.currentScript.closest('[data-status-root]') : null;
      const roots = own ? [own] : Array.from(document.querySelectorAll('[data-status-root]'));
      roots.forEach((root) => {
        if (root.dataset.initialized === 'true') return;
        root.dataset.initialized = 'true';
        init(root);
      });

      function init(root) {
        const payload = root.querySelector('.status-payload');
        let data = {};
        try {
          const raw = payload ? payload.value.replace(/<\/?q>/gi, '').trim() : '{}';
          data = JSON.parse(raw);
        } catch (error) {
          data = {};
        }

        const text = (value, fallback) => {
          if (value === undefined || value === null || value === '') return fallback;
          if (typeof value === 'object') return fallback;
          return String(value);
        };

        const setText = (selector, value, fallback) => {
          const element = root.querySelector(selector);
          if (element) element.textContent = text(value, fallback);
        };

        const number = (value, fallback) => {
          const parsed = Number(value);
          return Number.isFinite(parsed) ? parsed : fallback;
        };

        const meterData = (value) => {
          let current = 100;
          let max = 100;

          if (value && typeof value === 'object') {
            current = number(value.current, 100);
            max = number(value.max, 100);
          } else if (typeof value === 'string') {
            const ratio = value.match(/(-?\d+(?:\.\d+)?)\s*\/\s*(-?\d+(?:\.\d+)?)/);
            if (ratio) {
              current = number(ratio[1], 100);
              max = number(ratio[2], 100);
            } else {
              current = number(value.replace(/[^\d.-]/g, ''), 100);
            }
          } else if (value !== undefined && value !== null) {
            current = number(value, 100);
          }

          max = Math.max(1, max);
          current = Math.max(0, Math.min(max, current));
          return { current, max, percent: Math.round((current / max) * 100) };
        };

        const setMeter = (name, value) => {
          const meter = meterData(value);
          const valueEl = root.querySelector('[data-' + name + '-value]');
          const barEl = root.querySelector('[data-' + name + '-bar]');
          if (valueEl) valueEl.textContent = meter.current + ' / ' + meter.max;
          if (barEl) {
            barEl.style.width = '0%';
            requestAnimationFrame(() => {
              requestAnimationFrame(() => { barEl.style.width = meter.percent + '%'; });
            });
            if (name === 'hp' && meter.percent <= 30) barEl.dataset.level = 'low';
            barEl.setAttribute('role', 'progressbar');
            barEl.setAttribute('aria-valuemin', '0');
            barEl.setAttribute('aria-valuemax', String(meter.max));
            barEl.setAttribute('aria-valuenow', String(meter.current));
          }
        };

        const asArray = (value) => {
          if (Array.isArray(value)) return value;
          if (typeof value === 'string') return value.split(/[;\n,]+/).map((item) => item.trim()).filter(Boolean);
          return [];
        };

        const appendEmpty = (container, message) => {
          const empty = document.createElement('span');
          empty.className = 'empty-state';
          empty.textContent = message;
          container.appendChild(empty);
        };

        const statsEl = root.querySelector('[data-stats]');
        const stats = data.stats && typeof data.stats === 'object' && !Array.isArray(data.stats) ? data.stats : {};
        const standardStats = ['STR', 'AGI', 'VIT', 'DEF', 'INT', 'WIS', 'SPD', 'LUK'];
        const normalizedStats = {};
        Object.keys(stats).forEach((key) => {
          normalizedStats[key.toUpperCase()] = stats[key];
        });
        const statKeys = standardStats.concat(Object.keys(normalizedStats).filter((key) => !standardStats.includes(key)));

        statKeys.forEach((key, index) => {
          const card = document.createElement('div');
          card.className = 'stat-card';
          card.style.animationDelay = (index * 45) + 'ms';

          const label = document.createElement('span');
          label.className = 'stat-name';
          label.textContent = key;

          const value = document.createElement('span');
          value.className = 'stat-value';
          value.textContent = text(normalizedStats[key], '—');

          card.append(label, value);
          if (statsEl) statsEl.appendChild(card);
        });

        const equipmentEl = root.querySelector('[data-equipment]');
        const equipment = Array.isArray(data.equipment)
          ? data.equipment
          : (data.equipment && typeof data.equipment === 'object'
            ? Object.entries(data.equipment).map(([slot, item]) => ({ slot, item }))
            : []);

        if (equipmentEl) {
          equipment.forEach((entry, index) => {
            const slot = entry && typeof entry === 'object' ? text(entry.slot, 'Item ' + (index + 1)) : 'Item ' + (index + 1);
            const item = entry && typeof entry === 'object' ? text(entry.item || entry.name, 'Unspecified') : text(entry, 'Unspecified');
            const row = document.createElement('div');
            row.className = 'gear-row';

            const slotEl = document.createElement('span');
            slotEl.className = 'gear-slot';
            slotEl.textContent = slot;

            const itemEl = document.createElement('span');
            itemEl.className = 'gear-name';
            itemEl.textContent = item;

            row.append(slotEl, itemEl);
            equipmentEl.appendChild(row);
          });

          if (!equipment.length) appendEmpty(equipmentEl, 'No equipped items.');
        }

        const inventoryEl = root.querySelector('[data-inventory]');
        const inventory = asArray(data.inventory).map((item) => {
          if (item && typeof item === 'object') {
            const name = text(item.name || item.item, '');
            const quantity = item.quantity ? ' ×' + item.quantity : '';
            return name + quantity;
          }
          return text(item, '');
        }).filter(Boolean);

        if (inventoryEl) {
          inventory.forEach((item) => {
            const chip = document.createElement('span');
            chip.className = 'inventory-chip';
            chip.textContent = item;
            inventoryEl.appendChild(chip);
          });

          if (!inventory.length) appendEmpty(inventoryEl, 'No items carried.');
        }

        setText('[data-name]', data.name, '{{user}}');
        setText('[data-condition]', data.condition, 'Stable');
        setText('[data-condition-detail]', data.condition, 'Stable');
        setText('[data-path]', data.path, 'Unawakened');
        setText('[data-held-item]', data.held_item, 'Unspecified');
        setText('[data-skill]', data.skill, 'Unspecified');
        setText('[data-title]', data.title, 'Unassigned');
        setText('[data-outfit]', data.outfit, 'Unspecified');
        setMeter('hp', data.hp);
        setMeter('stamina', data.stamina);

        const tabs = Array.from(root.querySelectorAll('[role="tab"]'));
        const panels = Array.from(root.querySelectorAll('[role="tabpanel"]'));

        const activateTab = (tab, moveFocus) => {
          const targetId = tab.getAttribute('aria-controls');
          tabs.forEach((item) => {
            const selected = item === tab;
            item.setAttribute('aria-selected', String(selected));
            item.tabIndex = selected ? 0 : -1;
          });
          panels.forEach((panel) => {
            panel.hidden = panel.id !== targetId;
          });
          if (moveFocus) tab.focus();
        };

        tabs.forEach((tab, index) => {
          tab.addEventListener('click', () => activateTab(tab, false));
          tab.addEventListener('keydown', (event) => {
            let next = index;
            if (event.key === 'ArrowRight') next = (index + 1) % tabs.length;
            else if (event.key === 'ArrowLeft') next = (index - 1 + tabs.length) % tabs.length;
            else if (event.key === 'Home') next = 0;
            else if (event.key === 'End') next = tabs.length - 1;
            else return;
            event.preventDefault();
            activateTab(tabs[next], true);
          });
        });
      }
    })();
  </script>
